import DoodleCore
import Foundation

/// Files generated by the Python side and shipped in the app bundle.
struct BundledResources: Sendable {
    let catalog: Catalog
    let confidenceTable: ConfidenceTable
    let modelCard: ModelCard

    static func load(from bundle: Bundle = .main) throws -> BundledResources {
        BundledResources(
            catalog: try decode("catalog", from: bundle),
            confidenceTable: try decode("confidence_table", from: bundle),
            modelCard: try decode("model_card", from: bundle)
        )
    }

    private static func decode<Value: Decodable>(_ name: String, from bundle: Bundle) throws -> Value {
        guard let url = bundle.url(forResource: name, withExtension: "json") else {
            throw CocoaError(.fileNoSuchFile)
        }
        return try JSONDecoder().decode(Value.self, from: Data(contentsOf: url))
    }
}

struct Catalog: Decodable, Sendable {
    struct Chapter: Decodable, Identifiable, Sendable {
        let name: String
        let categories: [String]
        var id: String { name }
    }

    let chapters: [Chapter]

    var total: Int { chapters.reduce(0) { $0 + $1.categories.count } }

    func chapter(of category: String) -> Chapter? {
        chapters.first { $0.categories.contains(category) }
    }
}

struct ModelCard: Decodable, Sendable {
    let attribution: String
    let datasetUrl: String
    let classes: Int
    let testImages: Int
    let testTop1: Double
    let testTop5: Double
    let modelMegabytes: Double

    enum CodingKeys: String, CodingKey {
        case attribution, classes
        case datasetUrl = "dataset_url"
        case testImages = "test_images"
        case testTop1 = "test_top1"
        case testTop5 = "test_top5"
        case modelMegabytes = "model_megabytes"
    }
}
